export function BOMPDF({ 
  nestingReport, 
  report, 
  projectName = '', 
  companyName = 'Company Name',
  contactName = ''
}: BOMPDFProps) {
  console.log('[BOMPDF] Rendering NEW template version')
  
  // Calculate total tonnage from report data
  const totalTonnage = nestingReport.profiles.reduce((sum, profile) => {
    const profileData = report.profiles.find(p => p.profile_name === profile.profile_name)
    return sum + (profileData ? profileData.total_weight / 1000 : 0) // Convert kg to tonnes
  }, 0)

  // Calculate total length in meters
  const totalLength = nestingReport.profiles.reduce((sum, profile) => {
    return sum + (profile.total_length / 1000) // Convert mm to meters
  }, 0)

  // Count unique profile types
  const profileTypeCount = nestingReport.profiles.length

  // Get current date in DD/MM/YYYY format
  const currentDate = new Date().toLocaleDateString('en-GB', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  })

  // Prepare BOM data - group by profile and stock length
  const bomData: Array<{
    profileType: string
    stockLength: number
    amount: number
    weight: number
  }> = []

  nestingReport.profiles.forEach((profile) => {
    // Get profile data from report to calculate weight per meter
    const profileData = report.profiles.find(p => p.profile_name === profile.profile_name)
    
    // Calculate weight per meter (kg/m) from report data
    let weightPerMeter = 0
    if (profileData && profile.total_length > 0) {
      const totalLengthM = profile.total_length / 1000.0  // Convert mm to meters
      weightPerMeter = profileData.total_weight / totalLengthM  // kg per meter
    }
    
    // Use stock_lengths_used which contains the actual bar counts per stock length
    Object.entries(profile.stock_lengths_used).forEach(([stockLengthStr, barCount]) => {
      if (barCount > 0) {
        const stockLength = parseFloat(stockLengthStr)
        const stockLengthM = stockLength / 1000.0  // Convert to meters
        
        // Calculate tonnage: (weight_per_meter_kg) * (stock_length_m) * (number_of_bars) / 1000
        const tonnage = (weightPerMeter * stockLengthM * barCount) / 1000.0  // tonnes
        
        bomData.push({
          profileType: profile.profile_name,
          stockLength: stockLength,
          amount: barCount,
          weight: tonnage,
        })
      }
    })
  })

  // Sort by profile type, then by stock length
  bomData.sort((a, b) => {
    if (a.profileType !== b.profileType) {
      return a.profileType.localeCompare(b.profileType)
    }
    return a.stockLength - b.stockLength
  })

  return (
    <Document>
      <Page size="A4" style={styles.page}>
        {/* Header Section with Title and Company Info */}
        <View style={styles.headerSection}>
          {/* Title with Green Check */}
          <View style={styles.titleRow}>
            <View style={{ marginRight: 10 }}>
              <CheckCircleIcon />
            </View>
            <Text style={styles.title}>Bill of materials</Text>
          </View>

          {/* Company Information */}
          <View style={styles.companyInfo}>
            <View style={styles.companyRow}>
              <View style={styles.companyIcon}>
                <BuildingIcon />
              </View>
              <Text style={styles.companyText}>{companyName}</Text>
            </View>
            <View style={styles.companyRow}>
              <View style={styles.companyIcon}>
                <LocationIcon />
              </View>
              <Text style={styles.companyText}>Company Address</Text>
            </View>
            <View style={styles.companyRow}>
              <View style={styles.companyIcon}>
                <EnvelopeIcon />
              </View>
              <Text style={styles.companyText}>Company Email</Text>
            </View>
            <View style={styles.companyRow}>
              <View style={styles.companyIcon}>
                <TelephoneIcon />
              </View>
              <Text style={styles.companyText}>Company Phone Number</Text>
            </View>
            <View style={styles.companyRow}>
              <View style={styles.companyIcon}>
                <CalendarIcon />
              </View>
              <Text style={styles.companyText}>{currentDate}</Text>
            </View>
          </View>
        </View>

        {/* Divider */}
        <View style={styles.divider} />

        {/* Project Name Section */}
        <View style={styles.projectSection}>
          <View style={{ marginRight: 8 }}>
            <ProjectIcon />
          </View>
          <Text style={styles.projectName}>{projectName || 'Project Name'}</Text>
        </View>

        {/* Summary Box (Green Background) */}
        <View style={styles.summaryBox}>
          <View style={styles.summaryRow}>
            <Text style={styles.summaryLabel}>Total weight</Text>
            <Text style={styles.summaryValue}>{totalTonnage.toFixed(1)} (t)</Text>
          </View>
          <View style={styles.summaryRow}>
            <Text style={styles.summaryLabel}>Total length</Text>
            <Text style={styles.summaryValue}>{Math.round(totalLength)} (m)</Text>
          </View>
          <View style={styles.summaryRow}>
            <Text style={styles.summaryLabel}>Profile Type</Text>
            <Text style={styles.summaryValue}>{profileTypeCount}</Text>
          </View>
        </View>

        {/* Table Section */}
        <View style={styles.table}>
          {/* Table Header */}
          <View style={styles.tableHeader}>
            <Text style={[styles.tableHeaderText, styles.colProfileHeader]}>PROFILE NAME</Text>
            <Text style={[styles.tableHeaderText, styles.colLength]}>LENGTH (m)</Text>
            <Text style={[styles.tableHeaderText, styles.colQuantity]}>QUANTITY</Text>
            <Text style={[styles.tableHeaderText, styles.colWeight]}>WEIGHT (KG)</Text>
          </View>

          {/* Table Rows */}
          {bomData.map((row, index) => (
            <View key={index} style={styles.tableRow}>
              <Text style={[styles.tableText, styles.colProfileHeader]}>{row.profileType}</Text>
              <Text style={[styles.tableText, styles.colLength]}>{(row.stockLength / 1000).toFixed(1)}</Text>
              <Text style={[styles.tableText, styles.colQuantity]}>{row.amount}</Text>
              <Text style={[styles.tableText, styles.colWeight]}>{(row.weight * 1000).toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',')}</Text>
            </View>
          ))}
        </View>

        {/* Footer with Cutwize Logo */}
        <View style={styles.footerSection} fixed>
          <CutwiseLogo />
        </View>
      </Page>
    </Document>
  )
}
